@carlosparadis Given the yaml file:
```yml
filter:
   files:
     keep_filepaths_ending_with:
       - R
     remove_filepaths_containing:
       - test
    replies:
     filter_by_reply_author_substring:
           - "no-reply@apache.org"
           - "jenkins@builds.apache.org"
           - "bot"
           - "Hudson"
     filter_by_reply_subject_substring:
           - "Review Request"
           - "\\[VOTE\\]"
     filter_by_reply_body_substring:
           - "XXXX"
```
The 3 functions would be:
```r
filter_by_reply_author_substring <- function(dt_file, substring) {
  if (!all(c("reply_from", "reply_to") %in% colnames(dt_file))) {
    stop("The data.table must contain both 'reply_from' and 'reply_to' columns")
  }

  author_contains_re <- stri_c('(', stri_c(substring, collapse = "|"), ')')

  is_not_author_with_substring <- !(
    stri_detect_regex(dt_file$reply_from, author_contains_re, case_insensitive = TRUE) |
    stri_detect_regex(dt_file$reply_to, author_contains_re, case_insensitive = TRUE)
  )

  # Return filtered data
  return(dt_file[is_not_author_with_substring])
}
```
```r
filter_by_reply_subject_substring <- function(dt_file, substring) {
  if (!("reply_subject" %in% colnames(dt_file))) {
    stop("The data.table must contain a 'reply_subject' column")
  }

  subject_contains_re <- stri_c('(', stri_c(substring, collapse = "|"), ')')
  is_not_subject_with_substring <- !stri_detect_regex(
    dt_file$reply_subject,
    subject_contains_re,
    case_insensitive = TRUE
  )

  return(dt_file[is_not_subject_with_substring])
}
```
and 
```r
filter_by_reply_body_substring <- function(dt_file, substring) {
  if (!("reply_body" %in% colnames(dt_file))) {
    stop("The data.table must contain a 'reply_body' column")
  }

  body_contains_re <- stri_c('(', stri_c(substring, collapse = "|"), ')')
  is_not_body_with_substring <- !stri_detect_regex(
    dt_file$reply_body,
    body_contains_re,
    case_insensitive = TRUE
  )

  return(dt_file[is_not_body_with_substring])
}
```
Given your last comment "I find it is less likely that the filter one could apply to "from" will differ from the one from "to", since both are emails.", I've created a filter called filter_by_reply_author_substring() that applies filters to the reply_from and reply_to using the list with the same key name in the yml file. Additionally, i've included "bot" and "Hudson" under the filter_by_reply_author_substring key in the yml to accommodate refactoring the clean_jira_data() function. Now with these 3 filter functions, it is the refactored form of these 2 functions contained within R/Sentic.R:
```r
clean_jira_data <- function(df) {
  if (!("reply_from" %in% colnames(df))) {
    stop("The data frame does not contain a 'reply_from' column")
  }

  cleaned_df <- df[!grepl("bot", df$reply_from, ignore.case = TRUE), ]
  cleaned_df <- cleaned_df[!grepl("Hudson", cleaned_df$reply_from, ignore.case = TRUE), ]

  return(cleaned_df)
}
```
```r
clean_mbox_data <- function(df, if_clean_vote = TRUE) {
  if (!("reply_subject" %in% colnames(df)) || !("reply_from" %in% colnames(df))) {
    stop("The data frame does not contain 'reply_subject' or 'reply_from' columns")
  }

  cleaned_df <- df[!grepl("^\\[GitHub\\]|^\\[jira\\]", df$reply_subject, ignore.case = TRUE), ]
  cleaned_df <- cleaned_df[!grepl("HELIX-", cleaned_df$reply_subject), ]
  cleaned_df <- cleaned_df[!grepl("Review Request", cleaned_df$reply_subject, ignore.case = TRUE), ]
  cleaned_df <- cleaned_df[!grepl("no-reply@apache.org|jenkins@builds.apache.org", cleaned_df$reply_from), ]

  if (if_clean_vote) {
    cleaned_df <- cleaned_df[!grepl("\\[VOTE\\]", cleaned_df$reply_subject, ignore.case = TRUE), ]
  }

  return(cleaned_df)
}
```

